#include <Aevrynd/SkinnedModelAsset.h>
#include <cmath>
#include <chrono>
#include <fstream>
#include <iostream>

using namespace Aevrynd;
namespace {
void U32(std::vector<std::byte>& bytes,std::size_t offset,std::uint32_t value){for(unsigned shift=0;shift<32;shift+=8)bytes[offset++]=std::byte((value>>shift)&255);}
void U64(std::vector<std::byte>& bytes,std::size_t offset,std::uint64_t value){for(unsigned shift=0;shift<64;shift+=8)bytes[offset++]=std::byte((value>>shift)&255);}
std::uint32_t R32(const std::vector<std::byte>& bytes,std::size_t offset){std::uint32_t value{};for(unsigned shift=0;shift<32;shift+=8)value|=std::uint32_t(std::to_integer<unsigned>(bytes[offset++]))<<shift;return value;}
std::uint64_t R64(const std::vector<std::byte>& bytes,std::size_t offset){std::uint64_t value{};for(unsigned shift=0;shift<64;shift+=8)value|=std::uint64_t(std::to_integer<unsigned>(bytes[offset++]))<<shift;return value;}
std::size_t ChunkOffset(const std::vector<std::byte>& bytes,std::uint32_t type){for(std::size_t index=0;index<R32(bytes,32);++index){const std::size_t toc=64+index*32;if(R32(bytes,toc)==type)return std::size_t(R64(bytes,toc+8));}return 0;}
SkinnedModelAssetData Asset(){SkinnedModelAssetData data;const std::uint32_t normal=PackNormalSnorm8({0,1,0});data.model.bindMesh.vertices={{0,0,0,normal,0xff112233u,0,0},{1,0,0,normal,0xff445566u,1,0},{0,1,0,normal,0xff778899u,0,1},{1,1,0,normal,0xffaabbccu,1,1}};data.model.bindMesh.indices={0,1,2,2,1,3};JointTransform3D child{};child.translation={1,0,0};child.quaternion={0,0,0,1};child.usesQuaternion=true;data.model.skeleton.joints={{-1,{}},{0,child}};data.model.influences={{{0,0,0,0},{65535,0,0,0}},{{1,0,0,0},{65535,0,0,0}},{{0,1,0,0},{32768,32767,0,0}},{{1,0,0,0},{65535,0,0,0}}};data.model.inverseBindMatrices={Matrix4::Identity(),CreateTranslationMatrix({-1,0,0})};data.jointNames={"Root","Hand.L"};data.materialSlotNames={"Skin","Cloth"};data.materials={{{.72f,.42f,.31f,1},{.02f,.01f,0},1,.48f,0,.5f,1,1,SkinnedMaterialAlphaMode3D::Opaque,false,false},{{.04f,.18f,.12f,.82f},{.1f,.2f,.3f},2,.72f,.05f,.37f,-.5f,.8f,SkinnedMaterialAlphaMode3D::Blend,true,false}};data.submeshes={{0,3,0,0},{3,3,1,0}};AnimationKeyframe3D first{};first.transform=child;AnimationKeyframe3D second{};second.time=1;second.transform=child;second.transform.translation={2,0,0};data.clips.push_back({"Wave",{1,true,{{1,{first,second}}}}});return data;}
}

int main(){const SkinnedModelAssetData source=Asset();std::vector<std::byte> first,second;std::string error;if(!EncodeSkinnedModelAssetV2(source,first,&error)||!EncodeSkinnedModelAssetV2(source,second,&error)||first!=second){std::cerr<<"V2 deterministic encoding failed "<<error<<'\n';return 1;}const auto loaded=LoadSkinnedModelAssetDetailed(first);if(!loaded||loaded.asset.jointNames!=source.jointNames||loaded.asset.materialSlotNames!=source.materialSlotNames||loaded.asset.materials.size()!=2||loaded.asset.materials[1].alphaMode!=SkinnedMaterialAlphaMode3D::Blend||!loaded.asset.materials[1].doubleSided||std::abs(loaded.asset.materials[1].normalScale+.5f)>.0001f||loaded.asset.submeshes.size()!=2||loaded.asset.clips.size()!=1||loaded.asset.clips[0].name!="Wave"||loaded.asset.clips[0].clip.tracks[0].keyframes.size()!=2){std::cerr<<"V2 round trip failed "<<loaded.error<<'\n';return 2;}SkinnedModelAssetData legacy=source;legacy.materials.clear();std::vector<std::byte> legacyBytes;if(!EncodeSkinnedModelAssetV2(legacy,legacyBytes,&error)||!LoadSkinnedModelAssetDetailed(legacyBytes)||!LoadSkinnedModelAssetDetailed(legacyBytes).asset.materials.empty()){std::cerr<<"Old V2 material absence compatibility failed\n";return 11;}const AnimationPose3D pose=SampleAnimationClip(loaded.asset.model.skeleton,loaded.asset.clips[0].clip,.5f);if(std::abs(pose.localTransforms[1].translation.x-1.5f)>.0001f){std::cerr<<"V2 animation golden failed\n";return 3;}const auto stamp=std::chrono::steady_clock::now().time_since_epoch().count();const std::filesystem::path temporary=std::filesystem::temp_directory_path()/("aevrynd-aeskin-v2-"+std::to_string(stamp)+".aeskin");{std::ofstream file(temporary,std::ios::binary|std::ios::trunc);file.write(reinterpret_cast<const char*>(first.data()),std::streamsize(first.size()));if(!file){std::cerr<<"V2 temporary file write failed\n";return 9;}}const auto fileLoaded=LoadSkinnedModelAssetFileDetailed(temporary);std::error_code removeError;std::filesystem::remove(temporary,removeError);if(!fileLoaded||fileLoaded.asset.jointNames!=source.jointNames||removeError){std::cerr<<"V2 bounded file load failed "<<fileLoaded.error<<'\n';return 10;}
    std::vector<std::byte> damaged=first;damaged.pop_back();if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"V2 truncation accepted\n";return 4;}damaged=first;U64(damaged,64+8,64);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"V2 overlapping chunk accepted\n";return 5;}damaged=first;U32(damaged,64+28,27);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"V2 bad stride accepted\n";return 6;}damaged=first;U32(damaged,48,0);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"V2 submesh count mismatch accepted\n";return 7;}const std::size_t materialOffset=ChunkOffset(first,0x4c54414du);if(!materialOffset){std::cerr<<"MATL chunk missing\n";return 12;}damaged=first;U32(damaged,materialOffset+60,1);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"MATL reserved field accepted\n";return 13;}damaged=first;U32(damaged,materialOffset+4,3);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"MATL invalid alpha mode accepted\n";return 14;}damaged=first;U32(damaged,materialOffset+40,0x7fc00000u);if(LoadSkinnedModelAssetDetailed(damaged)){std::cerr<<"MATL NaN accepted\n";return 15;}SkinnedModelAssetData invalid=source;invalid.jointNames[1]="Root";std::vector<std::byte> sentinel{std::byte{9}};if(EncodeSkinnedModelAssetV2(invalid,sentinel,&error)||sentinel!=std::vector<std::byte>{std::byte{9}}){std::cerr<<"V2 failure was not atomic\n";return 8;}invalid=source;invalid.materials[0].emissiveStrength=65;if(EncodeSkinnedModelAssetV2(invalid,sentinel,&error)||sentinel!=std::vector<std::byte>{std::byte{9}}){std::cerr<<"MATL range failure was not atomic\n";return 16;}std::cout<<"v2Bytes="<<first.size()<<" submeshes=2 clips=1 materials=2\n";return 0;}
